package com.nigson.commerce.fulfillment;
import java.util.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.support.*;
import com.nigson.commerce.inventory.InventoryAuthority;
import com.nigson.commerce.platform.*;
import com.nigson.shared.events.EventCodec;
import com.nigson.shared.problem.*;
import com.nigson.shared.security.ActorAssertion;
public final class DeliveryRuleService {
 private final DeliveryRuleRepository repository;private final InventoryAuthority authority;private final JdbcTemplate jdbc;private final PlatformStore commands;private final AuditWriter audit;private final io.micrometer.core.instrument.MeterRegistry metrics;
 public DeliveryRuleService(DeliveryRuleRepository repository,InventoryAuthority authority,JdbcTemplate jdbc,PlatformStore commands,AuditWriter audit,io.micrometer.core.instrument.MeterRegistry metrics){this.repository=repository;this.authority=authority;this.jdbc=jdbc;this.commands=commands;this.audit=audit;this.metrics=metrics;}
 private PlatformStore.Response execute(ActorAssertion.Actor actor,String api,String key,Object request,UUID correlation,java.util.function.Supplier<PlatformStore.Response> change){authority.require(actor);ApiValues.idempotencyKey(key);if(correlation==null)throw ApiValues.invalid();ApiValues.uuid(correlation.toString());try{return commands.executeLocal(actor.party().toString(),api,key,EventCodec.JSON.valueToTree(request),db->{jdbc.execute("SET LOCAL lock_timeout='500ms'");jdbc.execute("SET LOCAL statement_timeout='2s'");authority.stabilize(actor);return change.get();});}catch(org.springframework.dao.DataAccessException failure){for(Throwable cause=failure;cause!=null;cause=cause.getCause())if(cause instanceof java.sql.SQLException sql&&Set.of("55P03","57014").contains(sql.getSQLState()))throw new Problem.Failure(ProblemCode.IDEMPOTENCY_IN_PROGRESS);throw failure;}}
 private void evidence(ActorAssertion.Actor actor,FulfillmentValues.Rule after,Long before,UUID correlation,boolean create){audit.append(actor.party().toString(),AuditValues.ActorKind.USER,create?AuditValues.Action.DELIVERY_RULE_CREATE:AuditValues.Action.DELIVERY_RULE_UPDATE,AuditValues.Resource.DELIVERY_RULE,after.id(),correlation,AuditValues.Reason.CONFIGURATION_CHANGE,before==null?null:Map.of("version",before),Map.of("version",after.version(),"enabled",after.active(),"amount",after.fee(),"currency","NGN"),null);TransactionSynchronizationManager.registerSynchronization(new TransactionSynchronization(){public void afterCommit(){metrics.counter("nigson.fulfillment.commands","operation",create?"RULE_CREATE":"RULE_UPDATE").increment();}});}
 public FulfillmentValues.Rule create(ActorAssertion.Actor actor,FulfillmentValues.RuleInput input,String key,UUID correlation){var response=execute(actor,"API-171",key,input,correlation,()->{var after=repository.create(input,actor.party().toString());evidence(actor,after,null,correlation,true);return new PlatformStore.Response(201,EventCodec.JSON.valueToTree(after),after.id());});return EventCodec.JSON.treeToValue(response.body(),FulfillmentValues.Rule.class);}
 public FulfillmentValues.Rule update(ActorAssertion.Actor actor,UUID id,long expected,FulfillmentValues.RuleInput input,String key,UUID correlation){authority.require(actor);repository.find(id,false);if(expected<0||expected==Long.MAX_VALUE)throw ApiValues.invalid();var response=execute(actor,"API-047",key,Map.of("id",id,"version",expected,"body",input),correlation,()->{var after=repository.update(id,expected,input,actor.party().toString());evidence(actor,after,expected,correlation,false);return new PlatformStore.Response(200,EventCodec.JSON.valueToTree(after),id);});return EventCodec.JSON.treeToValue(response.body(),FulfillmentValues.Rule.class);}
}
